import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十八卦 井 水风井 坎上巽下","description":"周易 - 第四十八卦 井 水风井 坎上巽下","frontmatter":{"title":"第四十八卦 井 水风井 坎上巽下","description":"周易 - 第四十八卦 井 水风井 坎上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/049.md","filePath":"zh/classics/zhouyi/049.md"}'),l={name:"zh/classics/zhouyi/049.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="井" tabindex="-1">井 <a class="header-anchor" href="#井" aria-label="Permalink to “井”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>改邑不改井，无丧无得，往来井井。汔至，亦未繘井，羸其瓶，凶。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>巽乎水而上水，井；井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>木上有水，井；君子以劳民劝相。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>井泥不食，旧井无禽。象曰：井泥不 食，下也。旧井无禽，时舍也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>井谷射鲋，瓮敝漏。象曰：井谷射鲋，无与也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>井渫不食，为我民恻，可用汲，王明，并受其福。象曰：井渫不食，行恻也。求王明，受福也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>井甃，无咎。象曰：井甃无咎，修井也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>井冽，寒泉食。象曰：寒泉之食，中正也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>井收勿幕，有孚无吉。象曰：元吉在上，大成也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
